describe('Access Denied Page Handling', () => {
    beforeEach(() => {
        cy.intercept('GET', '/api/protected-resource', {
            statusCode: 403,
            body: { message: 'Access Denied' }
        }).as('getProtectedResource');

        cy.visit('/protected-page');
    });

    it('should display the access denied page on 403 error', () => {
        cy.wait('@getProtectedResource');
        cy.get('.access-denied-message').should('be.visible');
        cy.get('.access-denied-message').contains('Access Denied');
    });

    it('should not show the access denied page if the user has access', () => {
        cy.intercept('GET', '/api/protected-resource', {
            statusCode: 200,
            body: { data: 'Protected Data' }
        }).as('getProtectedResourceWithAccess');

        cy.visit('/protected-page');
        cy.wait('@getProtectedResourceWithAccess');
        cy.get('.protected-content').should('be.visible');
        cy.get('.protected-content').contains('Protected Data');
    });
});
